insert into public.life_spheres (id, name, description, color, icon, sort_order) values
  ('health', 'Health & Energy', 'Sleep, movement, nourishment, and how your body feels day to day.', '#E07A5F', 'HeartPulse', 1),
  ('mind', 'Mind & Emotions', 'Inner calm, emotional resilience, and mental clarity.', '#9C89B8', 'Brain', 2),
  ('relationships', 'Friendships', 'The people who know you, laugh with you, and show up.', '#F2A65A', 'Users', 3),
  ('family', 'Family', 'Bonds with the family you were born into or chose.', '#C9805C', 'House', 4),
  ('love', 'Love & Intimacy', 'Romance, partnership, and closeness — including with yourself.', '#D96C8A', 'Heart', 5),
  ('career', 'Career & Craft', 'Meaningful work, skills, and professional direction.', '#5B8E7D', 'Briefcase', 6),
  ('finances', 'Finances', 'Security, freedom, and a calm relationship with money.', '#8AA05B', 'Wallet', 7),
  ('growth', 'Learning & Growth', 'Curiosity, new skills, and becoming who you want to be.', '#4F86A6', 'GraduationCap', 8),
  ('fun', 'Joy & Play', 'Hobbies, adventure, rest, and the art of doing nothing.', '#E9B949', 'PartyPopper', 9),
  ('home', 'Home & Environment', 'The spaces you live in and how they support you.', '#7D9B76', 'Trees', 10),
  ('community', 'Contribution', 'Giving back, belonging, and your mark on the world.', '#C77D58', 'HandHeart', 11),
  ('purpose', 'Purpose & Spirit', 'Meaning, values, faith, and what makes life feel whole.', '#7A6FA8', 'Sparkles', 12)
insert into public.months (id, title, subtitle, description, action_prompt, gallery_categories) values
  (1, 'Awakening', 'Notice where you are', 'Every story starts with a gentle look around. No judgement — just noticing.', 'Plan one small morning ritual that feels like a fresh start.', array['nature', 'cosmos']::text[]),
  (2, 'Roots', 'What holds you steady', 'Before growing up, we grow down. Explore the habits and people that ground you.', 'Schedule time with someone or something that grounds you.', array['botanical', 'nature']::text[]),
  (3, 'Bloom', 'Let something new open', 'Try one thing you''ve been curious about. Blooming is allowed to be imperfect.', 'Book a first try at something new — a class, a recipe, a route.', array['botanical', 'mandala']::text[]),
  (4, 'Momentum', 'Small steps, steady rhythm', 'Momentum is gentle repetition. Find a rhythm that fits your real life.', 'Pick one tiny repeatable action and put the first one on your calendar.', array['geometric', 'ocean']::text[]),
  (5, 'Connection', 'The threads between us', 'We are shaped by the people we let in. Tend to one relationship with intention.', 'Plan a call, letter, or visit with someone you miss.', array['mandala', 'botanical']::text[]),
  (6, 'Midpoint', 'Pause and breathe', 'Halfway. Look back with kindness and forward with curiosity. Adjusting is wisdom.', 'Block an unhurried hour for a solo check-in date.', array['ocean', 'cosmos']::text[]),
  (7, 'Courage', 'One brave thing', 'Courage is often quiet. Choose one thing that stretches you, kindly.', 'Schedule the brave conversation or step you''ve been postponing.', array['geometric', 'mandala']::text[]),
  (8, 'Abundance', 'Notice what is enough', 'Shift from scarcity to sufficiency. Celebrate resources you already have.', 'Plan a moment to enjoy something you already own or love.', array['botanical', 'nature']::text[]),
  (9, 'Harvest', 'Gather what has grown', 'Collect the fruits of your effort — even the unexpected ones.', 'Plan a small celebration of something you completed.', array['nature', 'geometric']::text[]),
  (10, 'Letting Go', 'Make room', 'Release what no longer fits — habits, expectations, or old stories about yourself.', 'Plan a gentle clearing: a drawer, a commitment, a calendar block.', array['cosmos', 'ocean']::text[]),
  (11, 'Gratitude', 'Thank the path', 'Look back at the road with warmth. Gratitude makes the journey visible.', 'Plan to write a thank-you note to someone (or to yourself).', array['mandala', 'botanical']::text[]),
  (12, 'Homecoming', 'The next chapter', 'You authored a year. Celebrate who you''ve become and dream the next story.', 'Plan a ritual to close this year and open the next.', array['cosmos', 'mandala']::text[])
insert into public.reflection_tasks (id, month_id, prompt, hint, kind, sort_order) values
  ('m1-q1', 1, '{name}, what is quietly asking for your attention right now?', 'Let the first answer come, even if it surprises you.', 'text', 1),
  ('m1-q2', 1, 'If {focus} felt 10% lighter this month, what would be different?', 'Think of one concrete, visible change.', 'text', 2),
  ('m1-q3', 1, 'How hopeful do you feel about the year ahead?', '1 is tender, 10 is radiant. Both are welcome.', 'scale', 3),
  ('m2-q1', 2, 'Which daily habit makes you feel most like yourself?', 'Small things count — a walk, a song, a cup of tea.', 'text', 1),
  ('m2-q2', 2, 'Who or what helped you get here? What would you thank them for?', 'Gratitude is a root system.', 'text', 2),
  ('m2-q3', 2, 'How supported do you feel in your goal: “{goal}”?', 'Support can be people, tools, or time.', 'scale', 3),
  ('m3-q1', 3, 'What have you been curious about but haven''t tried yet?', 'Name it without needing a plan.', 'text', 1),
  ('m3-q2', 3, 'What would you attempt in {focus} if you couldn''t get it wrong?', 'Imagine the kindest version of yourself cheering you on.', 'text', 2),
  ('m4-q1', 4, 'What''s the smallest step toward “{goal}” you could take this week?', 'Smaller than you think. Then halve it.', 'text', 1),
  ('m4-q2', 4, 'When do you naturally have the most energy during the day?', 'Plan with your energy, not against it.', 'text', 2),
  ('m4-q3', 4, 'How sustainable does your current pace feel?', '1 is exhausting, 10 is effortless.', 'scale', 3),
  ('m5-q1', 5, 'Who makes you feel most at home? When did you last tell them?', 'A sentence is enough.', 'text', 1),
  ('m5-q2', 5, 'What kind of friend, partner, or family member do you want to be?', 'Describe it in three words.', 'text', 2),
  ('m6-q1', 6, '{name}, what are you proud of from the first half of your journey?', 'Include the invisible wins.', 'text', 1),
  ('m6-q2', 6, 'Is {focus} still the right focus? What would you change?', 'Changing direction is not failing. You can update priorities anytime.', 'text', 2),
  ('m6-q3', 6, 'How aligned does your life feel with what matters to you?', 'Just a snapshot, not a grade.', 'scale', 3),
  ('m7-q1', 7, 'What fear has been making decisions for you lately?', 'Naming it gently shrinks it.', 'text', 1),
  ('m7-q2', 7, 'What brave step toward “{goal}” would future-you thank you for?', 'It can be small and still be brave.', 'text', 2),
  ('m8-q1', 8, 'What do you already have more of than you realise?', 'Time, skills, kindness, people…', 'text', 1),
  ('m8-q2', 8, 'What does “enough” look like for you in {focus}?', 'Enough is a finish line you get to draw.', 'text', 2),
  ('m9-q1', 9, 'What has grown in you since you began this journey?', 'Skills, beliefs, boundaries, friendships.', 'text', 1),
  ('m9-q2', 9, 'Which effort toward “{goal}” paid off in a surprising way?', 'Not every harvest looks like the seed.', 'text', 2),
  ('m9-q3', 9, 'How nourished do you feel by your progress?', '1 is depleted, 10 is full.', 'scale', 3),
  ('m10-q1', 10, 'What are you ready to set down, {name}?', 'You can always pick it back up later.', 'text', 1),
  ('m10-q2', 10, 'Which expectation about {focus} isn''t really yours?', 'Whose voice is it?', 'text', 2),
  ('m11-q1', 11, 'List three moments from this year you''d like to remember forever.', 'Tiny moments are often the brightest.', 'text', 1),
  ('m11-q2', 11, 'What would you like to thank yourself for?', 'Speak to yourself like a dear friend.', 'text', 2),
  ('m12-q1', 12, '{name}, how would you title this chapter of your life?', 'A book title, a song, a single word.', 'text', 1),
  ('m12-q2', 12, 'What did {focus} teach you this year?', 'Lessons can be soft or sharp.', 'text', 2),
  ('m12-q3', 12, 'How at peace do you feel with your year?', 'Every number is a valid ending.', 'scale', 3)
